/** 快速查询: 按 offset 获取段 (O(n), debug用) */
export function getSegmentByOffset(offset: number): SegmentEntry | undefined {
  return segmentTable.find(s => s.offset === offset);
}

/** 快速查询: 按 id 获取段 (O(1) via id === index) */
export function getSegmentById(id: number): SegmentEntry | undefined {
  return segmentTable[id];
}

