/** 读取整个 bank 原始数据 */
export function getBank03Data(): readonly number[] {
  return PRG_BANK_03_DATA;
}

/** 读取 bank 内偏移的单字节 (带 0x1FFF wrap) */
export function rom03(offset: number): number {
  return PRG_BANK_03_DATA[offset & 0x1FFF] ?? 0;
}

/** 读取 bank 内偏移的 16-bit 小端指针 (带 0x1FFF wrap) */
export function rom03Ptr16(offset: number): number {
  const lo = PRG_BANK_03_DATA[offset & 0x1FFF] ?? 0;
  const hi = PRG_BANK_03_DATA[(offset + 1) & 0x1FFF] ?? 0;
  return (hi << 8) | lo;
}
